"""Styles for the provider connection modal."""

CONNECTION_CSS = "\n    ConnectionScreen {\n        align: center middle;\n    }\n\n    #connection-dialog {\n        width: 68;\n        height: 30;\n        max-width: 94%;\n        max-height: 92%;\n        padding: 0;\n        border: round $primary;\n        background: $surface;\n    }\n\n    #connection-header {\n        height: 4;\n        padding-left: 2;\n        background: $primary;\n        color: $text;\n    }\n\n    #connection-heading {\n        width: 1fr;\n        height: 4;\n        padding-top: 1;\n    }\n\n    #connection-title {\n        height: 1;\n        text-style: bold;\n    }\n\n    #connection-subtitle {\n        height: 1;\n        color: $text-muted;\n    }\n\n    #connection-close {\n        width: 5;\n        min-width: 5;\n        height: 4;\n        margin: 0;\n        border: none;\n        background: $primary;\n        color: $text;\n    }\n\n    #connection-close:hover {\n        background: $error;\n    }\n\n    #connection-scroll {\n        height: 1fr;\n        padding: 0 2 1 2;\n        scrollbar-size: 1 1;\n    }\n\n    #connection-dialog .section-title {\n        width: 100%;\n        height: 2;\n        margin-top: 1;\n        padding-top: 1;\n        color: $accent;\n        text-style: bold;\n        border-bottom: solid $panel-lighten-1;\n    }\n\n    #connection-dialog .field-label {\n        height: 1;\n        margin-top: 1;\n        color: $text-muted;\n    }\n\n    #connection-dialog .row {\n        height: 3;\n        width: 100%;\n        align: center middle;\n    }\n\n    #verify-ssl-radio {\n        width: 100%;\n        height: 3;\n        layout: horizontal;\n        border: none;\n        padding: 0;\n    }\n\n    #verify-ssl-radio RadioButton {\n        width: auto;\n        margin-right: 2;\n    }\n\n    #connection-actions {\n        height: 4;\n        padding: 0 2;\n        align: right middle;\n        border-top: solid $panel-lighten-1;\n        background: $panel;\n    }\n\n    #connection-actions Button {\n        margin-left: 1;\n    }\n\n    #connection-dialog .filter-row {\n        height: 3;\n        width: 100%;\n    }\n\n    #connection-dialog .filter-row Select {\n        width: 1fr;\n        margin-right: 1;\n    }\n\n    /* SelectCurrent is auto-height by default. Long values can wrap to two\n       lines, making it taller than the three-row filter container and clipping\n       the bottom border. Keep the closed control to one line instead. */\n    #connection-dialog .filter-row SelectCurrent Static#label {\n        height: 1;\n        text-overflow: ellipsis;\n    }\n\n    #connection-dialog .filter-row Input {\n        width: 1fr;\n    }\n    "
